### Wrap
```js
function wrap(v, half){ if(v>half) v-=half*2; else if(v<-half) v+=half*2; return v; }
function wrapDelta(d, half){ // shortest signed delta across the seam
  const span = half*2; if(d>half) d-=span; else if(d<-half) d+=span; return d;
}
```

Collision across the seam: use wrapDelta for the distance vector, then compare squared distance. That handles torus collisions correctly.

### Audio engine

```js
const Audio = (()=> {
  let ctx=null, master=null, thrGain=null, started=false, muted=false;
  function ensure(){
    if(ctx) return ctx;
    const AC = window.AudioContext||window.webkitAudioContext;
    if(!AC) return null;
    ctx = new AC();
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value=-14; comp.knee.value=22; comp.ratio.value=10; comp.attack.value=0.003; comp.release.value=0.25;
    master = ctx.createGain(); master.gain.value=0.9;
    master.connect(comp); comp.connect(ctx.destination);
    // noise buffer
    ...
    // thrust loop
    ...
    return ctx;
  }
  ...
})();
```

