```js
function laser(){
  const t=ctx.currentTime; 
  const o=ctx.createOscillator(); o.type='sawtooth';
  o.frequency.setValueAtTime(880,t); o.frequency.exponentialRampToValueAtTime(140,t+0.18);
  const g=ctx.createGain(); g.gain.setValueAtTime(0.0001,t);
  g.gain.exponentialRampToValueAtTime(0.28,t+0.008);
  g.gain.exponentialRampToValueAtTime(0.0001,t+0.2);
  const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.setValueAtTime(4200,t); f.frequency.exponentialRampToValueAtTime(600,t+0.2);
  o.connect(f); f.connect(g); g.connect(master); o.start(t); o.stop(t+0.22);
  // click noise
}
```

pop(size): noise burst through bandpass.
```js
function boom(size=1, big=false){
  const t=ctx.currentTime; const dur = big?1.0:0.32;
  const src=ctx.createBufferSource(); src.buffer=noiseBuf; src.loop=true;
  const bp=ctx.createBiquadFilter(); bp.type='bandpass'; bp.Q.value=1.1;
  bp.frequency.setValueAtTime(big?420:1400*(1.6/size),t);
  bp.frequency.exponentialRampToValueAtTime(big?60:180,t+dur);
  const g=ctx.createGain(); g.gain.setValueAtTime(big?0.5:0.22,t);
  g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
  src.connect(bp);bp.connect(g);g.connect(master);src.start(t);src.stop(t+dur+0.05);
  // low thump
  const o=ctx.createOscillator(); o.type='sine'; o.frequency.setValueAtTime(big?150:110,t); o.frequency.exponentialRampToValueAtTime(30,t+dur);
  const og=ctx.createGain(); og.gain.setValueAtTime(big?0.45:0.15,t); og.gain.exponentialRampToValueAtTime(0.0001,t+dur);
  o.connect(og);og.connect(master); o.start(t); o.stop(t+dur);
}
```

