function asteroidMat(color){
  return new THREE.ShaderMaterial({
    uniforms: { uColor:{value:new THREE.Color(color)}, uRim:{value:new THREE.Color(0x7ff6ff)}, uOpacity:{value:1} },
    vertexShader: `
      varying vec3 vN; varying vec3 vP;
      void main(){
        vN = normalize(normalMatrix * normal);
        vec4 mv = modelViewMatrix * vec4(position,1.0);
        vP = -mv.xyz;
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: `
      uniform vec3 uColor; uniform vec3 uRim;
      varying vec3 vN; varying vec3 vP;
      void main(){
        float f = 1.0 - max(dot(normalize(vN), normalize(vP)), 0.0);
        float rim = pow(f, 2.5);
        vec3 c = uColor * 0.35 + uRim * rim * 1.2;
        gl_FragColor = vec4(c, 1.0);
      }`,
    side: THREE.FrontSide
  });
}
```

