### Particles shader

```glsl
// vertex
attribute float aSize; attribute float aAlpha; attribute vec3 aColor;
varying vec3 vC; varying float vA;
void main(){
  vC = aColor; vA = aAlpha;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * (260.0 / max(0.001, -mv.z));
  gl_Position = projectionMatrix * mv;
}
// fragment
varying vec3 vC; varying float vA;
void main(){
  vec2 uv = gl_PointCoord - vec2(0.5);
  float d = length(uv);
  if(d > 0.5) discard;
  float a = smoothstep(0.5, 0.02, d);
  gl_FragColor = vec4(vC, vA * a);
}
```

Note: gl_PointSize scaling — the camera is at z=26 looking at origin, so -mv.z ≈ 26 for gameplay objects. 260/26 ≈ 10 → a particle with aSize=1 is 10px. Reasonable. I'll tune aSize values ~0.3-1.2.

