```js
function aiUpdate(dt){
  const out = { left:false, right:false, thrust:false, fire:false };
  if(!ship.alive) return out;
  // Gather threats
  let bestTarget=null, bestScore=-1e9;
  let avx=0, avy=0, threatCount=0;
  for(const a of asteroids){
    const dx = wrapDelta(ship.x - a.x, FIELD_X);
    const dy = wrapDelta(ship.y - a.y, FIELD_Y);
    const d = Math.hypot(dx,dy) || 0.001;
    const rvx = ship.vx - a.vx, rvy = ship.vy - a.vy;
    const closing = -(dx*rvx + dy*rvy); // >0 if approaching
    // closest approach
    const tca = closing>0 ? d*d/ (Math.hypot(rvx,rvy)**2 || 1e-6) : 0;
    const sep = Math.max(0.1, Math.hypot(dx - rvx*tca, dy - rvy*tca));
    if(sep < a.r + ship.r + 3.0 && tca < 2.2) threatCount++;
    if(sep < a.r + ship.r + 4.5 && closing > 0){
      const w = (1/(d+0.5)) * (1/ (0.6 + tca));
      avx += (dx/d)*w; avy += (dy/d)*w;
    }
    // target score
    let s = 14 - d/FIELD_X*8 + (a.size===2?1.2:0) + (threat? 6:0);
    if(s>bestScore){ bestScore=s; bestTarget=a; }
  }
  ...
}
```

