import re, sys, json

src = open('index.html').read()

src = src.replace("'https://cdn.jsdelivr.net/npm/three@0.159.0/build/three.min.js',", "'three.min.js',")
src = src.replace("'https://unpkg.com/three@0.159.0/build/three.min.js',", "'three.min.js',")
src = src.replace("'https://cdnjs.cloudflare.com/ajax/libs/three.js/0.159.0/three.min.js'", "'three.min.js'")

err_shim = """<script>
window.__errs=[];
window.addEventListener('error',function(e){window.__errs.push((e.message||'?')+' @'+(e.filename||'?')+':'+(e.lineno||0));});
window.addEventListener('unhandledrejection',function(e){window.__errs.push('rejection: '+e.reason);});
</script>
"""
src = src.replace('<style>', err_shim + '<style>', 1)

expose = """window.__game = {
  get ship(){return ship;},
  get asteroids(){return asteroids;},
  get bullets(){return bullets;},
  get state(){return state;},
  get autopilot(){return autopilot;},
  get score(){return score;},
  get lives(){return lives;},
  get wave(){return wave;},
  get parts(){return pLive;},
  get audioReady(){return Sound.ready;}
};
requestAnimationFrame(frame);

};"""
assert src.count('requestAnimationFrame(frame);\n\n};') == 1
src = src.replace('requestAnimationFrame(frame);\n\n};', expose)

diag = """<div id="diag" style="display:none">PENDING</div>
<script>
(function(){
  var log = { errors: window.__errs, samples: [], splitSeen: 0, maxScore: 0, maxWave: 1,
              minLives: 3, states: {}, deaths: 0, fired: 0 };
  var lastLives = 3;
  function snap(tag){
    var g = window.__game;
    if(!g) { log.samples.push({tag:tag, ready:false}); return; }
    var small = 0, med = 0, big = 0;
    for(var i=0;i<g.asteroids.length;i++){
      var s = g.asteroids[i].size;
      if(s===2) small++; else if(s===1) med++; else big++;
    }
    var onBullets = 0;
    for(var j=0;j<g.bullets.length;j++) if(g.bullets[j].on) onBullets++;
    var rec = { tag: tag, state: g.state, auto: g.autopilot, score: g.score, lives: g.lives,
                wave: g.wave, ast: g.asteroids.length, big: big, med: med, small: small,
                bullets: onBullets, parts: g.parts.length,
                sx: +g.ship.x.toFixed(2), sy: +g.ship.y.toFixed(2),
                sv: +Math.hypot(g.ship.vx,g.ship.vy).toFixed(2),
                alive: g.ship.alive, audio: g.audioReady };
    log.samples.push(rec);
    log.states[g.state] = (log.states[g.state]||0)+1;
    if(small>0) log.splitSeen++;
    if(g.score>log.maxScore) log.maxScore=g.score;
    if(g.wave>log.maxWave) log.maxWave=g.wave;
    if(g.lives<lastLives){ log.deaths++; lastLives=g.lives; }
    if(g.lives<log.minLives) log.minLives=g.lives;
  }
  setInterval(function(){ if(window.__game) snap('tick'); }, 250);
  setTimeout(function(){ snap('A_attract_2s'); }, 2000);
  setTimeout(function(){
    snap('B_before_input');
    window.dispatchEvent(new KeyboardEvent('keydown', {code:'Space', bubbles:true}));
    window.dispatchEvent(new KeyboardEvent('keydown', {code:'KeyW', bubbles:true}));
    setTimeout(function(){ window.dispatchEvent(new KeyboardEvent('keyup', {code:'KeyW', bubbles:true}));
                           window.dispatchEvent(new KeyboardEvent('keyup', {code:'Space', bubbles:true})); }, 120);
  }, 2500);
  setTimeout(function(){ snap('C_after_input'); }, 3000);
  setTimeout(function(){ snap('D_idle_3s_later'); }, 6200);
  setTimeout(function(){ snap('E_final_12s'); }, 12000);
  setTimeout(function(){
    log.errors = window.__errs.slice();
    var el = document.getElementById('diag');
    el.textContent = 'RESULT:' + JSON.stringify(log);
  }, 12500);
})();
</script>
"""
src = src.replace('</body>', diag + '</body>', 1)
open('.verify/test.html','w').write(src)
print("harness written", len(src))

