input.content:
import re, sys, json

src = open('index.html').read()

src = src.replace("'https://cdn.jsdelivr.net/npm/three@0.159.0/build/three.min.js',", "'three.min.js',")
src = src.replace("'https://unpkg.com/three@0.159.0/build/three.min.js',", "'three.min.js',")
src = src.replace("'https://cdnjs.cloudflare.com/ajax/libs/three.js/0.159.0/three.min.js'", "'three.min.js'")

err_shim = """<script>
window.__errs=[];
window.addEventListener('error',function(e){window.__errs.push((e.message||'?')+' @'+(e.filename||'?')+':'+(e.lineno||0));});
window.addEventListener('unhandledrejection',function(e){window.__errs.push('rejection: '+e.reason);});
</script>
"""
src = src.replace('<style>', err_shim + '<style>', 1)

expose = """window.__game = {
  get ship(){return ship;},
  get asteroids(){return asteroids;},
  get bullets(){return bullets;},
  get state(){return state;},
  get autopilot(){return autopilot;},
  get score(){return score;},
  get lives(){return lives;},
  get wave(){return wave;},
  get parts(){return pLive;},
  get rings(){return rings;},
  get audioReady(){return Sound.ready;},
  get restarts(){return __restarts;},
  function restart(){ __restarts++; restart(); }
};
var __restarts = 0;
renderer.render = function(){};
window.requestAnimationFrame = function(){ return 0; };
(function(){
  var t = performance.now();
  setInterval(function(){ t += 1000/60; frame(t); }, 1);
})();

};"""
assert src.count('requestAnimationFrame(frame);\n\n};') == 1
src = src.replace('requestAnimationFrame(frame);\n\n};', expose)

diag = """<div id="diag" style="display:none">PENDING</div>
<script>
(function(){
  var log = { errors: [], samples: [], ticks: 0, splitTicks: 0, maxScore: 0, maxWave: 1,
              deaths: 0, sawSmall: 0, sawMed: 0, sawBullet: 0, sawParts: 0, sawOver: 0,
              sawRespawn: 0, sawAttract: 0, states: {}, gameTime: 0 };
  var lastLives = 3, lastState = '';
  function snap(tag){
    var g = window.__game;
    if(!g){ log.samples.push({tag:tag, ready:false}); return; }
    var small=0, med=0, big=0;
    for(var i=0;i<g.asteroids.length;i++){
      var s=g.asteroids[i].size;
      if(s===2) small++; else if(s===1) med++; else big++;
    }
    var on=0;
    for(var j=0;j<g.bullets.length;j++) if(g.bullets[j].on) on++;
    log.ticks++;
    log.samples.push({ tag: tag, st: g.state, auto: g.autopilot, sc: g.score, lv: g.lives,
      wv: g.wave, ast: g.asteroids.length, big: big, med: med, sm: small, bl: on,
      pt: g.parts.length, sx: +g.ship.x.toFixed(1), sy: +g.ship.y.toFixed(1),
      sv: +Math.hypot(g.ship.vx,g.ship.vy).toFixed(1), alive: g.ship.alive });
    log.states[g.state] = (log.states[g.state]||0)+1;
    if(small>0) log.splitTicks++;
    if(med>0) log.sawMed=1;
    if(small>0) log.sawSmall=1;
    if(on>0) log.sawBullet=1;
    if(g.parts.length>5) log.sawParts=1;
    if(g.state==='over') log.sawOver=1;
    if(g.state==='respawn') log.sawRespawn=1;
    if(g.state==='attract') log.sawAttract=1;
    if(g.score>log.maxScore) log.maxScore=g.score;
    if(g.wave>log.maxWave) log.maxWave=g.wave;
    if(g.lives<lastLives){ log.deaths++; lastLives=g.lives; }
  }
  setInterval(function(){ snap('t'); }, 100);
  setTimeout(function(){ snap('A_2s_attract'); }, 2000);
  setTimeout(function(){
    window.dispatchEvent(new KeyboardEvent('keydown', {code:'Space', bubbles:true}));
    window.dispatchEvent(new KeyboardEvent('keydown', {code:'KeyW', bubbles:true}));
    setTimeout(function(){
      window.dispatchEvent(new KeyboardEvent('keyup', {code:'KeyW', bubbles:true}));
      window.dispatchEvent(new KeyboardEvent('keyup', {code:'Space', bubbles:true}));
    }, 100);
    setTimeout(function(){ snap('C_just_after_input'); }, 200);
    setTimeout(function(){ snap('D_idle_plus_2s'); }, 2000);
    setTimeout(function(){ snap('E_idle_plus_4s_AI_BACK'); }, 4000);
  }, 2500);
  setTimeout(function(){
    window.__game.restart();
    snap('F_after_restart');
  }, 7000);
  setTimeout(function(){
    window.dispatchEvent(new KeyboardEvent('keydown', {code:'KeyP', bubbles:true}));
    setTimeout(function(){ snap('G_paused'); window.dispatchEvent(new KeyboardEvent('keydown', {code:'KeyP', bubbles:true})); }, 300);
    setTimeout(function(){ snap('H_resumed'); }, 800);
  }, 8000);
  setTimeout(function(){ window.dispatchEvent(new KeyboardEvent('keydown', {code:'KeyM', bubbles:true})); snap('I_mute_toggled'); }, 9500);
  setTimeout(function(){
    snap('J_final');
    log.errors = window.__errs.slice();
    document.getElementById('diag').textContent = 'RESULT:' + JSON.stringify(log);
  }, 11500);
})();
</script>
"""
src = src.replace('</body>', diag + '</body>', 1)
open('.verify/test.html','w').write(src)
print("harness written", len(src))

import re, json, sys

d = open('.verify/dom.html').read()
m = re.search(r'RESULT:(\{.*?\})</div>', d, re.S)
if not m:
    m2 = re.search(r'id="diag"[^>]*>(.*?)</div>', d, re.S)
    print("RAW:", (m2.group(1)[:800] if m2 else "NO DIAG ELEMENT"))
    sys.exit(1)
r = json.loads(m.group(1))

print("== ERRORS ==", r['errors'] if r['errors'] else "none")
print("== ticks ==", r['ticks'], "| states:", r['states'])
print("== maxScore ==", r['maxScore'], "maxWave ==", r['maxWave'], "deaths ==", r['deaths'])
print("== observed: splitTicks=%d med=%d small=%d bullets=%d particles=%d over=%d respawn=%d attract=%d" % (
    r['splitTicks'], r['sawMed'], r['sawSmall'], r['sawBullet'], r['sawParts'],
    r['sawOver'], r['sawRespawn'], r['sawAttract']))
print("== keyframes ==")
for s in r['samples']:
    if s['tag'] != 't':
        print(" ", json.dumps(s))
print("== timeline (every 5th tick) ==")
ts = [s for s in r['samples'] if s['tag'] == 't']
for s in ts[::5]:
    print("  %s st=%-8s auto=%-5s sc=%-5s lv=%s wv=%-2s ast=%-2d(b%d/m%d/s%d) bl=%d pt=%d ship=(%s,%s) v=%s alive=%s" % (
        s['tag'], s['st'], s['auto'], s['sc'], s['lv'], s['wv'], s['ast'],
        s['big'], s['med'], s['sm'], s['bl'], s['pt'], s['sx'], s['sy'], s['sv'], s['alive']))

fails = []
if r['errors']: fails.append("runtime errors: %s" % r['errors'][:3])
if r['maxScore'] <= 0: fails.append("AI never scored in attract mode")
if not r['sawSmall'] and not r['sawMed']: fails.append("asteroids never split")
if not r['sawBullet']: fails.append("no bullets ever fired")
if not r['sawParts']: fails.append("no particles spawned")
kf = {s['tag']: s for s in r['samples'] if s['tag'] != 't'}
if kf.get('A_2s_attract', {}).get('st') != 'attract': fails.append("did not boot into attract mode")
if kf.get('A_2s_attract', {}).get('auto') is not True: fails.append("attract mode not on autopilot")
if kf.get('C_just_after_input', {}).get('auto') is not False: fails.append("input did not take control")
if kf.get('D_idle_plus_2s', {}).get('auto') is not False: fails.append("autopilot engaged before 3s idle")
if kf.get('E_idle_plus_4s_AI_BACK', {}).get('auto') is not True: fails.append("autopilot did not engage after 3s idle")
if kf.get('G_paused', {}).get('st') != 'paused': fails.append("P did not pause")
if kf.get('H_resumed', {}).get('st') == 'paused': fails.append("P did not resume")
if kf.get('F_after_restart', {}).get('sc') != 0: fails.append("restart did not reset score")

print("\n== RESULT ==", "PASS" if not fails else "FAIL")
for f in fails: print("  X", f)

