function snap(tag){
  var g = window.__game;
  if(!g){ log.samples.push({tag:tag, ready:false}); return; }
  var small=0, med=0, big=0;
  for(var i=0;i<g.asteroids.length;i++){
    var s=g.asteroids[i].size;
    if(s===2) small++; else if(s===1) med++; else big++;
  }
  var on=0;
  for(var j=0;j<g.bullets.length;j++) if(g.bullets[j].on) on++;
  log.ticks++;
  log.samples.push({ tag: tag, st: g.state, auto: g.autopilot, sc: g.score, lv: g.lives,
    wv: g.wave, ast: g.asteroids.length, big: big, med: med, sm: small, bl: on,
    pt: g.parts.length, sx: +g.ship.x.toFixed(1), sy: +g.ship.y.toFixed(1),
    sv: +Math.hypot(g.ship.vx,g.ship.vy).toFixed(1), alive: g.ship.alive,
    dscore: document.getElementById('score').textContent,
    dwave: document.getElementById('wave').textContent,
    overHidden: document.getElementById('gameover').classList.contains('hidden'),
    badge: document.getElementById('badge').textContent,
    badgeHidden: document.getElementById('badge').classList.contains('hidden'),
    bannerHidden: document.getElementById('banner').classList.contains('hidden'),
    fatalHidden: document.getElementById('fatal').classList.contains('hidden'),
    canvas: !!document.querySelector('canvas') });

