python3 - <<'PY'
src=open('.verify/shot.html').read()
src=src.replace("window.__frozen = true;", """window.__frozen = true;
  (function(){
    var gl = renderer.getContext();
    var w = gl.drawingBufferWidth, h = gl.drawingBufferHeight;
    var px = new Uint8Array(w*h*4);
    gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,px);
    var nonblack=0, sum=0, maxv=0;
    for(var i=0;i<px.length;i+=4){
      var v=(px[i]+px[i+1]+px[i+2])/3;
      if(v>6) nonblack++; sum+=v; if(v>maxv) maxv=v;
    }
    var c=document.createElement('canvas'); c.width=w; c.height=h;
    var ctx2=c.getContext('2d');
    var img=ctx2.createImageData(w,h);
    for(var y=0;y<h;y++){
      var srcRow=(h-1-y)*w*4, dstRow=y*w*4;
      img.data.set(px.subarray(srcRow,srcRow+w*4), dstRow);
    }
    ctx2.putImageData(img,0,0);
    var d=document.createElement('div'); d.id='rinfo'; d.style.display='none';
    d.textContent='PNG:'+c.toDataURL('image/jpeg',0.92)+
      '|STATS:'+JSON.stringify({w:w,h:h,nonblackPct:+(100*nonblack/(w*h)).toFixed(2),
      avgLum:+(sum/(w*h)).toFixed(2),maxLum:maxv});
    document.body.appendChild(d);
  })();""")
