import sys

src = open('index.html').read()
src = src.replace("'https://cdn.jsdelivr.net/npm/three@0.159.0/build/three.min.js',", "'three.min.js',")
src = src.replace("'https://unpkg.com/three@0.159.0/build/three.min.js',", "'three.min.js',")
src = src.replace("'https://cdnjs.cloudflare.com/ajax/libs/three.js/0.159.0/three.min.js'", "'three.min.js'")
src = src.replace("antialias: true, powerPreference: 'high-performance'",
                  "antialias: true, powerPreference: 'high-performance', preserveDrawingBuffer: true")

shot = """window.requestAnimationFrame = function(){ return 0; };
(function(){
  var t = performance.now();
  var FRAMES = parseInt(location.hash.slice(1) || '200', 10);
  var KEY = location.search.indexOf('player') >= 0;
  for (var i = 0; i < FRAMES; i++){
    if (KEY && i === 4){
      window.dispatchEvent(new KeyboardEvent('keydown', {code:'KeyW', bubbles:true}));
      window.dispatchEvent(new KeyboardEvent('keydown', {code:'Space', bubbles:true}));
    }
    if (KEY && i === 150){
      window.dispatchEvent(new KeyboardEvent('keydown', {code:'KeyA', bubbles:true}));
      window.dispatchEvent(new KeyboardEvent('keydown', {code:'ArrowRight', bubbles:true}));
    }
    if (KEY && i === 240){
      window.dispatchEvent(new KeyboardEvent('keyup', {code:'KeyA', bubbles:true}));
      window.dispatchEvent(new KeyboardEvent('keyup', {code:'ArrowRight', bubbles:true}));
    }
    t += 1000/60;
    frame(t);
  }
  var bx = wrapPos(ship.x + 3.5, FIELD_X), by = wrapPos(ship.y + 1.5, FIELD_Y);
  burst(bx, by, 150, 0xffffff, 0x6ff6ff, 13, 1.5, 0.95, 1.2);
  burst(bx, by, 50, 0xffb347, 0xff5fd2, 8, 2.0, 0.7, 1.6);
  shockwave(bx, by, 2, 0x9ff4ff);
  shake = 1.3;
  for (var k = 0; k < 14; k++){ t += 1000/60; frame(t); }
  window.__frozen = true;

  var gl = renderer.getContext();
  var w = gl.drawingBufferWidth, h = gl.drawingBufferHeight;
  var px = new Uint8Array(w*h*4);
  gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,px);
  var nonblack=0, sum=0;
  for(var q=0;q<px.length;q+=4){
    var v=(px[q]+px[q+1]+px[q+2])/3;
    if(v>6) nonblack++; sum+=v;
  }
  var c=document.createElement('canvas'); c.width=w; c.height=h;
  var ctx2=c.getContext('2d');
  var img=ctx2.createImageData(w,h);
  for(var y=0;y<h;y++){
    var s0=(h-1-y)*w*4;
    img.data.set(px.subarray(s0,s0+w*4), y*w*4);
  }
  ctx2.putImageData(img,0,0);
  var d=document.createElement('div'); d.id='rinfo'; d.style.display='none';
  d.textContent='PNG:'+c.toDataURL('image/jpeg',0.92)+
    '|STATS:'+JSON.stringify({w:w,h:h,nonblackPct:+(100*nonblack/(w*h)).toFixed(2),
    avgLum:+(sum/(w*h)).toFixed(2),state:state,score:score,lives:lives,autopilot:autopilot,
    particles:pLive.length,asteroids:asteroids.length,errors:window.__errs||[]});
  document.body.appendChild(d);
})();

};"""
assert src.count('requestAnimationFrame(frame);\n\n};') == 1
src = src.replace('requestAnimationFrame(frame);\n\n};', shot)

err_shim = "<script>window.__errs=[];window.addEventListener('error',function(e){window.__errs.push(e.message);});</script>\n"
src = src.replace('<style>', err_shim + '<style>', 1)
open('.verify/shot.html','w').write(src)
print("shot harness written")

