var rings = [];
var ringWhite = new THREE.Color(0xffffff);
for (var ri = 0; ri < 5; ri++){
  var rg = new THREE.RingGeometry(0.87, 1.0, 64);
  var rm = new THREE.Mesh(rg, new THREE.MeshBasicMaterial({
    color: 0x9ff4ff, transparent: true, opacity: 0, side: THREE.FrontSide,
    blending: THREE.AdditiveBlending, depthWrite: false
  }));
  rm.visible = false;
  scene.add(rm);
  rings.push({ mesh: rm, t: 0, dur: 1, size: 1 });
}
function shockwave(x, y, size, color){
  for (var i = 0; i < rings.length; i++){
    if (rings[i].t <= 0){
      var m = rings[i].mesh;
      m.position.set(x, y, 0.15);
      m.material.color.set(color).lerp(ringWhite, 0.5);
      m.visible = true;
      rings[i].t = rings[i].dur = 0.42 + size * 0.16;
      rings[i].size = 3.0 + size * 1.7;
      return;
    }
  }
}
function updateRings(dt){
  for (var i = 0; i < rings.length; i++){
    var r = rings[i];
    if (r.t <= 0) continue;
    r.t -= dt;
    var k = 1 - r.t / r.dur;
    r.mesh.scale.setScalar(0.2 + k * r.size);
    r.mesh.material.opacity = (1 - k) * (1 - k) * 0.62;
    if (r.t <= 0) r.mesh.visible = false;
  }
}

